
-- CommandProject: big match (generated by the launcher). The game's lobby has 8 slots; a match
-- started by the launcher with  /map <scenario> /cpmatch <spec>  skips it and takes every start
-- position of the map, each one human, AI or empty, on any team.
--   spec = <options>|<slot 1>|<slot 2>|...
--   options = key=value;key=value   (Victory, UnitCap, FogOfWar, GameSpeed, NoRushOption, ...;
--             RestrictedCategories=AIR,NUKE is a list, DoNotShareUnitCap=true|false a boolean)
--   slot = kind,team,faction,ai,color   kind H (you), A (AI) or X (empty); team 1 = alone, 2+ = allies;
--                                   faction 0 = random, 1 UEF, 2 Cybran, 3 Illuminate;
--                                   color = index in GameColors (0-based, as the engine reads it)
-- Maps with more than 8 bases are saved with type 'cp_bigmatch' so the game's lobby (8 positions,
-- it crashes with more) does not list them; here they become a normal skirmish.
local function CPSplit(s, sep)
    local out = {}
    local start = 1
    while true do
        local i = string.find(s, sep, start, true)
        if not i then
            table.insert(out, string.sub(s, start))
            return out
        end
        table.insert(out, string.sub(s, start, i - 1))
        start = i + 1
    end
end

-- diagnostic switches (extra command line arguments): each one turns a part off, to find what
-- a given game install does not accept
local function CPOff(name)
    local ok, on = pcall(HasCommandLineArg, '/cpno' .. name)
    return ok and on
end

-- the engine keeps armies in 32-bit masks: 32 armies at most, counting the map's civilians.
-- 24 players + civilians played fine, 32 + civilians closed the game while loading
local CPMaxArmies = 32

function CPBigMatchSession(mapName, spec)
    if FixupMapName then mapName = FixupMapName(mapName) end
    local scenario = import('/lua/ui/maputil.lua').LoadScenario(mapName)
    if not scenario then error('CommandProject: mapa nao encontrado: ' .. tostring(mapName)) end
    VerifyScenarioConfiguration(scenario)
    scenario.type = 'skirmish'
    local parts = CPSplit(spec, '|')

    local options = table.copy(defaultOptions)
    options.Victory = 'demoralization'
    options.CheatsEnabled = 'false'
    if not CPOff('opts') then
        options.TeamLock = 'locked'
        -- the same options the game's skirmish screen sets
        options.NoNIS = false
        options.TeamSpawn = 'fixed'
        options.AllowObservers = false
        options.Ranked = false
        options.PreBuiltUnits = 'Off'
        options.RestrictedCategories = {}
    end
    for _, kv in CPSplit(parts[1] or '', ';') do
        local eq = string.find(kv, '=', 1, true)
        if eq and eq > 1 then options[string.sub(kv, 1, eq - 1)] = string.sub(kv, eq + 1) end
    end
    -- values that are not plain text for the game: the unit restrictions are a list and the
    -- unit cap sharing is read as true/false by the simulation
    if type(options.RestrictedCategories) == 'string' then
        local list = {}
        for _, key in CPSplit(options.RestrictedCategories, ',') do
            if key ~= '' then table.insert(list, key) end
        end
        options.RestrictedCategories = list
    end
    if options.DoNotShareUnitCap == 'false' then options.DoNotShareUnitCap = false
    elseif options.DoNotShareUnitCap == 'true' then options.DoNotShareUnitCap = true end
    scenario.Options = options

    local sessionInfo = {}
    sessionInfo.playerName = Prefs.GetFromCurrentProfile('Name') or 'Player'
    sessionInfo.createReplay = false
    sessionInfo.scenarioInfo = scenario
    sessionInfo.teamInfo = {}
    -- the game's own skirmish screen plays with the official expansion mod (its units, AI and
    -- research); without it the match stops loading
    local Mods = import('/lua/system/mods.lua')
    local okDlc, dlc = pcall(function() return Mods.GetOfficialDLCModForSession() end)
    if CPOff('dlc') then okDlc = false end
    if okDlc and type(dlc) == 'table' and table.getn(dlc) > 0 then
        sessionInfo.scenarioMods = dlc
    else
        sessionInfo.scenarioMods = Mods.GetCampaignMods(scenario)
    end

    local armies = scenario.Configurations.standard.teams[1].armies
    local factions = table.getn(import('/lua/common/factions.lua').Factions)
    local colors = table.getn(import('/lua/common/gameColors.lua').GameColors.PlayerColors)
    local human, others = false, {}
    local loadingFaction = 1
    for index = 1, table.getn(armies) do
        local name = armies[index]
        local s = CPSplit(parts[index + 1] or 'X', ',')
        local kind = s[1]
        if kind == 'H' or kind == 'A' or kind == 'G' then
            local p = import('/lua/ui/lobby/lobbyComm.lua').GetDefaultPlayerOptions(sessionInfo.playerName)
            local faction = tonumber(s[3] or '0') or 0
            if faction < 1 or faction > factions then faction = GetRandomFaction() end
            p.Faction = faction
            p.Team = math.max(1, tonumber(s[2] or '1') or 1)
            if CPOff('teams') then p.Team = 1 end
            p.ArmyName = name
            if not CPOff('spot') then p.StartSpot = index end
            -- the engine reads the color 0-based (FactionColors[faction][color + 1])
            local color = tonumber(s[5] or '') or (index - 1)
            p.PlayerColor = math.mod(math.max(0, color), colors)
            if CPOff('color') then p.PlayerColor = math.mod(index, 10) end
            p.ArmyColor = p.PlayerColor
            if kind == 'H' and not human then
                p.Human = true
                p.PlayerName = sessionInfo.playerName
                human = p
                loadingFaction = faction
            elseif kind == 'G' then
                -- a friend's base (match with invites): filled when the friend connects
                p.Human = true
                p.CPGuest = true
                p.PlayerName = 'Convidado'
                table.insert(others, p)
            else
                p.Human = false
                p.AIPersonality = (s[4] and s[4] ~= '') and s[4] or 'Normal'
                p.PlayerName = GetRandomName(faction, p.AIPersonality)
                table.insert(others, p)
            end
        end
    end
    if not human and table.getn(others) == 0 then error('CommandProject: nenhum jogador na partida') end
    -- the human first: the game expects the local player among the first entries
    if CPOff('order') then
        -- the order of the bases (as the game's own command line does)
        local all = {}
        if human then table.insert(all, human) end
        for _, p in others do table.insert(all, p) end
        table.sort(all, function(a, b) return a.StartSpot < b.StartSpot end)
        for _, p in all do table.insert(sessionInfo.teamInfo, p) end
    else
        if human then table.insert(sessionInfo.teamInfo, human) end
        for _, p in others do table.insert(sessionInfo.teamInfo, p) end
    end
    if table.getn(sessionInfo.teamInfo) > CPMaxArmies then
        error('CommandProject: ' .. table.getn(sessionInfo.teamInfo) .. ' players, the game takes ' .. CPMaxArmies .. ' at most')
    end
    local size = scenario.size or {}
    LOG('*CommandProject big match: ' .. table.getn(sessionInfo.teamInfo) .. ' players on ' .. tostring(mapName) .. ' (' .. tostring(size[1]) .. 'x' .. tostring(size[2]) .. ')')
    if not human then options.FullAI = true end

    -- the civilians (empty on maps made by the launcher) stay out when there is no room for them
    local extras = MapUtils.GetExtraArmies(scenario)
    if extras then
        for _, armyName in extras do
            if table.getn(sessionInfo.teamInfo) >= CPMaxArmies then
                WARN('*CommandProject big match: no room for the civilian army ' .. tostring(armyName) .. ' (' .. CPMaxArmies .. ' armies at most)')
                break
            end
            local p = import('/lua/ui/lobby/lobbyComm.lua').GetDefaultPlayerOptions('civilian')
            p.PlayerName = 'civilian'
            p.Civilian = true
            p.ArmyName = armyName
            p.Human = false
            table.insert(sessionInfo.teamInfo, p)
        end
    end

    local seed = GetCommandLineArg('/seed', 1)
    if seed then sessionInfo.RandomSeed = tonumber(seed[1]) end
    Prefs.SetToCurrentProfile('LoadingFaction', loadingFaction)
    return sessionInfo
end

-- climas do mod Climas (o launcher monta para o mapa e o clima da partida)
local CPBM_WEATHERS = { rain = true, storm = true, blizzard = true, fog = true, sandstorm = true }

-- o clima já montado nesta abertura do jogo (o launcher põe /lua/cpweatherinfo.lua no mod Climas)
local function CPWeatherMounted(map, kind)
    local ok, info = pcall(import, '/lua/cpweatherinfo.lua')
    if not ok or type(info) ~= 'table' or not info.kind then return false end
    return info.kind == kind and string.lower(tostring(info.map or '')) == string.lower(tostring(map or ''))
end

-- the big match screen inside the game (scene cp_bigmatch, made by the launcher): players in all,
-- number of teams (0 = everyone for himself), AI difficulty and the map. You take the first base,
-- the AIs the next ones; the bases of a team are side by side in the map's order. Capped by the
-- bases of the map, the 32 armies of the engine and the memory of big maps (as the launcher does).
-- friends = true: the other bases are for friends (the room below); the empty ones become AI
function CPBigMatchQuick(mapName, players, teams, ai, faction, victory, unitCap, friends)
    local MapUtils = import('/lua/ui/maputil.lua')
    local scenario = MapUtils.LoadScenario(mapName)
    if not scenario then error('CommandProject: mapa nao encontrado: ' .. tostring(mapName)) end
    local armies = scenario.Configurations.standard.teams[1].armies
    local bases = table.getn(armies)
    local size = (scenario.size and scenario.size[1]) or 1024
    local area = math.max(1, size / 1024) * math.max(1, size / 1024)
    local memory = math.max(2, math.floor(256 / area + 0.000001))
    local n = math.min(tonumber(players) or 8, bases, CPMaxArmies, memory)
    if n < 2 then n = 2 end
    teams = tonumber(teams) or 2
    if teams > n then teams = n end
    if ai ~= 'Easy' and ai ~= 'Normal' and ai ~= 'Hard' and ai ~= 'Cheat' then ai = 'Normal' end
    faction = tonumber(faction) or 0
    if faction < 0 or faction > 3 then faction = 0 end
    if victory ~= 'demoralization' and victory ~= 'domination' and victory ~= 'sandbox' then victory = 'demoralization' end
    unitCap = tonumber(unitCap) or 1000
    if unitCap < 50 or unitCap > 2000 then unitCap = 1000 end
    -- minigame (CPMinigames.lua no mod): guardado na sala ou nos atalhos do submenu Batalha
    local mode = CPBMGet('mode') or ''
    local known = { total = true, arena = true, defense = true, domination = true, supreme = true, survival = true, koth = true, vip = true, race = true, treasure = true }
    if not known[mode] then mode = '' end
    if mode == 'arena' then
        victory = 'eradication'
    elseif mode ~= '' and victory == 'sandbox' then
        victory = 'demoralization'
    end
    if (mode == 'defense' or mode == 'survival') and teams < 2 then teams = 2 end
    local spec = 'Victory=' .. victory .. ';UnitCap=' .. unitCap .. ';FogOfWar=explored;GameSpeed=normal;NoRushOption=Off;PreBuiltUnits=Off;PrebuiltUnits=Off;CivilianAlliance=enemy;CheatsEnabled=' .. tostring(CPBMGet('cheats') == true) .. ';DoNotShareUnitCap=true'
    if mode ~= '' then spec = spec .. ';CPMode=' .. mode end
    -- mutadores e eventos (EXTRAS na sala)
    local mut = tostring(CPBMGet('mut') or '')
    if string.find(mut, '^[a-z,]*$') and mut ~= '' then spec = spec .. ';CPMut=' .. mut end
    if CPBMGet('events') == true then spec = spec .. ';CPEvents=1' end
    local weather = tostring(CPBMGet('weather') or '')
    if CPBM_WEATHERS[weather] and CPWeatherMounted(mapName, weather) then spec = spec .. ';CPWeather=' .. weather end
    for i = 1, bases do
        if i <= n then
            local team = 1
            if teams >= 2 then team = math.floor((i - 1) * teams / n) + 2 end
            if i == 1 then
                spec = spec .. '|H,' .. team .. ',' .. faction .. ',,' .. (i - 1)
            else
                if friends then
                    spec = spec .. '|G,' .. team .. ',0,,' .. (i - 1)
                else
                    spec = spec .. '|A,' .. team .. ',0,' .. ai .. ',' .. (i - 1)
                end
            end
        else
            spec = spec .. '|X'
        end
    end
    LOG('*CommandProject big match (in game): ' .. n .. ' players, ' .. teams .. ' teams, ' .. ai .. ', faction ' .. faction .. ', ' .. victory .. ', cap ' .. unitCap .. ', mode ' .. mode .. ' on ' .. tostring(mapName))
    -- para o "Jogar de novo" da tela de resultado
    CPBMSet('last', { mapName, n, teams, ai, faction, victory, unitCap, mode })
    if friends then
        CPNet.ai = ai
        CPNet.fromMenu = true
        CPNetOpen({ host = true, map = mapName, spec = spec, mode = mode })
        return
    end
    LaunchSinglePlayerSession(CPBigMatchSession(mapName, spec))
end

-- escolhas da Partida grande feitas dentro do jogo (sala de batalha, submenus): guardadas no
-- perfil do jogo, valem para as próximas partidas
local CPBM_DEFAULT = { players = 8, teams = 2, ai = 'Normal', faction = 0, victory = 'demoralization', units = 1000, cheats = false, mode = '', mut = '', events = false, weather = '' }

function CPBMGet(key)
    local ok, saved = pcall(function() return import('/lua/user/prefs.lua').GetFromCurrentProfile('CPBigMatch') end)
    if ok and type(saved) == 'table' and saved[key] ~= nil then return saved[key] end
    return CPBM_DEFAULT[key]
end

function CPBMSet(key, value)
    pcall(function()
        local Prefs = import('/lua/user/prefs.lua')
        local saved = Prefs.GetFromCurrentProfile('CPBigMatch')
        if type(saved) ~= 'table' then saved = {} end
        saved[key] = value
        Prefs.SetToCurrentProfile('CPBigMatch', saved)
        if SavePreferences then SavePreferences() end
    end)
    LOG('*CommandProject big match option: ' .. tostring(key) .. ' = ' .. tostring(value))
end

-- MODO na sala: partida normal (com o tipo de vitória) ou um dos minigames
function CPBMSetMode(mode, victory)
    CPBMSet('mode', mode or '')
    if victory and victory ~= '' then CPBMSet('victory', victory) end
end

-- EXTRAS na sala: combinações prontas de mutadores e eventos
function CPBMSetExtras(mut, events)
    CPBMSet('mut', mut or '')
    CPBMSet('events', events and true or false)
end

-- atalhos dos minigames no submenu Batalha: o modo vale só para esta partida
function CPBigMatchMinigame(mapName, players, teams, mode)
    local before = CPBMGet('mode')
    CPBMSet('mode', mode)
    CPBigMatchQuick(mapName, players, teams, CPBMGet('ai'), CPBMGet('faction'), CPBMGet('victory'), CPBMGet('units'))
    CPBMSet('mode', before or '')
end

-- pedido para o launcher: o jogo grava no perfil (Game.prefs, que ele salva ao fechar) e fecha; o
-- launcher lê quando o jogo fecha e continua de lá: monta o clima e abre o jogo direto na partida
-- ('match'), abre a sala com amigos com estas escolhas ('room') ou a tela de entrar numa sala
-- ('join'). O número sobe a cada pedido: o launcher atende cada um uma vez só.
function CPLaunchRequest(action, map, extra)
    local ok, err = pcall(function()
        local Prefs = import('/lua/user/prefs.lua')
        local old = Prefs.GetFromCurrentProfile('CPLaunchRequest')
        local seq = ((type(old) == 'table' and tonumber(old.seq)) or 0) + 1
        local req = {
            seq = seq, action = action, map = tostring(map or ''),
            players = tonumber(CPBMGet('players')) or 8, teams = tonumber(CPBMGet('teams')) or 2,
            ai = tostring(CPBMGet('ai') or 'Normal'), faction = tonumber(CPBMGet('faction')) or 0,
            victory = tostring(CPBMGet('victory') or 'demoralization'), units = tonumber(CPBMGet('units')) or 1000,
            mode = tostring(CPBMGet('mode') or ''), mut = tostring(CPBMGet('mut') or ''),
            events = CPBMGet('events') == true, weather = tostring(CPBMGet('weather') or ''),
        }
        for k, v in extra or {} do req[k] = v end
        Prefs.SetToCurrentProfile('CPLaunchRequest', req)
        SavePreferences()
    end)
    if not ok then
        WARN('*CommandProject launcher request failed: ' .. tostring(err))
        return false
    end
    LOG('*CommandProject launcher request: ' .. tostring(action) .. ' (the game closes, the launcher goes on)')
    ExitApplication()
    return true
end

-- "Iniciar partida grande": as escolhas guardadas; o mapa guardado, se ainda existir. Com clima, o
-- launcher precisa montar o clima para o mapa: se o desta abertura já é o mesmo, começa aqui; senão
-- o jogo fecha e o launcher abre de novo direto na partida
function CPBigMatchFromMenu(defaultMap)
    local map = CPBMGet('map')
    if not map or not import('/lua/ui/maputil.lua').LoadScenario(map) then map = defaultMap end
    local weather = tostring(CPBMGet('weather') or '')
    if CPBM_WEATHERS[weather] and not CPWeatherMounted(map, weather) then
        if CPLaunchRequest('match', map) then return end
    end
    CPBigMatchQuick(map, CPBMGet('players'), CPBMGet('teams'), CPBMGet('ai'), CPBMGet('faction'), CPBMGet('victory'), CPBMGet('units'))
end

-- "Sala com amigos" (painel da Batalha e Multijogador): a sala do launcher, com as escolhas daqui
-- (lista de quem está, IAs nas vagas livres, convite, IP/LAN). A interface feita em Lua não aparece
-- nos menus do jogo, então a sala fica no launcher, que depois abre o jogo de todos juntos.
function CPRoomFromMenu(defaultMap)
    local map = CPBMGet('map')
    if not map or not import('/lua/ui/maputil.lua').LoadScenario(map) then map = defaultMap end
    CPLaunchRequest('room', map)
end

-- "Entrar numa sala" (Multijogador): a tela de entrar com o convite no launcher ('group' = a sala do
-- último amigo que convidou)
function CPRoomJoinFromMenu(which)
    CPLaunchRequest('join', CPBMGet('map') or '', { join = tostring(which or '') })
end

-- "Jogar de novo" (tela de resultado): a última partida grande com as mesmas escolhas
function CPBigMatchAgain()
    local l = CPBMGet('last')
    if type(l) ~= 'table' or not l[1] then
        LOG('*CommandProject: nenhuma partida grande para repetir')
        return
    end
    local before = CPBMGet('mode')
    CPBMSet('mode', l[8] or '')
    CPBigMatchQuick(l[1], l[2], l[3], l[4], l[5], l[6], l[7])
    CPBMSet('mode', before or '')
end

-- modos prontos do submenu Batalha: jogadores e times fixos, o resto das escolhas guardadas
function CPBigMatchMode(mapName, players, teams)
    CPBigMatchQuick(mapName, players, teams, CPBMGet('ai'), CPBMGet('faction'), CPBMGet('victory'), CPBMGet('units'))
end

-- pedidos para o launcher feitos dentro do jogo (Extras -> painel do launcher): perfil, mods,
-- cor da tela inicial, memória e prioridade. Ficam no perfil do jogo (Game.prefs) com um número
-- que sobe a cada mudança; o launcher aplica na próxima vez que você clica em Jogar.
local function CPLauncherSave(change)
    pcall(function()
        local Prefs = import('/lua/user/prefs.lua')
        local req = Prefs.GetFromCurrentProfile('CPLauncher')
        if type(req) ~= 'table' then req = {} end
        change(req)
        req.seq = (tonumber(req.seq) or 0) + 1
        Prefs.SetToCurrentProfile('CPLauncher', req)
        if SavePreferences then SavePreferences() end
    end)
end

function CPLauncherSet(key, value)
    CPLauncherSave(function(req) req[key] = value end)
    LOG('*CommandProject launcher request: ' .. tostring(key) .. ' = ' .. tostring(value))
end

function CPLauncherMod(id, on)
    CPLauncherSave(function(req)
        if type(req.mods) ~= 'table' then req.mods = {} end
        req.mods[id] = on and true or false
    end)
    LOG('*CommandProject launcher request: mod ' .. tostring(id) .. ' = ' .. tostring(on))
end

-- perfil de mods para a próxima vez que o jogo abrir pelo launcher (ele lê no Game.prefs)
function CPNextProfile(id)
    pcall(function()
        local Prefs = import('/lua/user/prefs.lua')
        Prefs.SetToCurrentProfile('CPNextProfile', id)
        if SavePreferences then SavePreferences() end
    end)
    LOG('*CommandProject next profile: ' .. tostring(id))
end

-- called first thing by StartCommandLineSession: true when the big match took over
function CPBigMatchStart(mapName)
    if not HasCommandLineArg('/cpmatch') then return false end
    local a = GetCommandLineArg('/cpmatch', 1)
    if not a or not a[1] then return false end
    -- match with friends (invite from the launcher): the network lobby below
    if HasCommandLineArg('/cphost') or HasCommandLineArg('/cpjoin') then
        local ok, err = pcall(CPNetStart, mapName, a[1])
        if ok then return true end
        WARN('*CommandProject big match (network): ' .. tostring(err))
        return false
    end
    local ok, info = pcall(CPBigMatchSession, mapName, a[1])
    if not ok then
        WARN('*CommandProject big match: ' .. tostring(info) .. ' (starting the normal match instead)')
        return false
    end
    LaunchSinglePlayerSession(info)
    return true
end


---------------------------------------------------------------------------- room with friends
-- A room of the CommandProject inside the game, for the big match with friends (up to 32
-- armies, minigames). The host opens it (launcher invite with /cphost <port>, or Battle ->
-- "Sala com amigos" in the game) and each friend connects straight to the host's game (launcher
-- invite with /cpjoin <address>, or Multiplayer -> "Entrar na sala de um amigo"): same network,
-- VPN (Radmin, ZeroTier) or the host's port open on the router. In the room every player picks
-- faction, color and team, everybody sees the same list (the host sends it), and the host starts
-- the match for all with the game's own network session (lobby comm). Bases nobody took become AI.
CPNet = { comm = false, host = false, info = false, panel = false, lines = {}, started = false, view = false, myId = false, hostId = false, ai = 'Normal', fromMenu = false }

local CPNET_ACCENT = 'FF2B8CFF'
local CPNET_BUTTON = 'FF1C2733'

local function CPArg(name)
    local ok, a = pcall(GetCommandLineArg, name, 1)
    if ok and a and a[1] then return a[1] end
    return nil
end

local function CPNetColors()
    local ok, n = pcall(function() return table.getn(import('/lua/common/gameColors.lua').GameColors.PlayerColors) end)
    if ok and n and n > 0 then return n end
    return 10
end

-- the bright color of an army (the one of the minimap)
local function CPNetSwatch(faction, color)
    local ok, c = pcall(function()
        local fc = import('/lua/common/gameColors.lua').GameColors.FactionColors
        local list = fc[(faction >= 1 and faction <= 3) and faction or 1]
        return list[math.mod(color, table.getn(list)) + 1].icon
    end)
    if ok and c then return c end
    return 'FFFFFFFF'
end

local function CPNetFactionName(f)
    if f == 1 then return 'UEF' elseif f == 2 then return 'Cybran' elseif f == 3 then return 'Illuminate' end
    return LOC('<LOC CP_NET_RANDOM>Random')
end

local function CPNetTeamName(t)
    if not t or t <= 1 then return LOC('<LOC CP_NET_ALONE>Alone') end
    return LOCF('<LOC CP_NET_TEAM>Team %d', t - 1)
end

-- host: the room as everybody sees it
local function CPNetSlots()
    local out = {}
    for i, p in CPNet.info.teamInfo do
        if not p.Civilian then
            local kind = 'A'
            if p.CPGuest then
                if p.OwnerID then kind = 'F' else kind = 'G' end
            elseif p.Human then
                kind = 'H'
            end
            table.insert(out, {
                name = tostring(p.PlayerName or ''), faction = p.CPFaction or p.Faction or 0, color = p.PlayerColor or 0,
                team = p.Team or 1, kind = kind, owner = p.OwnerID or '',
            })
        end
    end
    return out
end

local function CPNetMine()
    if not CPNet.view or not CPNet.myId then return nil end
    for _, s in CPNet.view.slots or {} do
        if s.owner == CPNet.myId then return s end
    end
    return nil
end

function CPNetClose()
    if CPNet.comm then pcall(function() CPNet.comm:Destroy() end) end
    if CPNet.panel then pcall(function() CPNet.panel:Destroy() end) end
    CPNet.comm, CPNet.panel, CPNet.view, CPNet.started, CPNet.info = false, false, false, false, false
    CPNet.lines = {}
    if not CPNet.fromMenu then ExitApplication() end
end

local function CPNetButton(parent, items, label, x, y, w, h, onClick)
    local UIUtil = import('/lua/ui/uiutil.lua')
    local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
    local Bitmap = import('/lua/maui/bitmap.lua').Bitmap
    local b = Bitmap(parent)
    b:SetSolidColor(CPNET_BUTTON)
    b.Width:Set(w)
    b.Height:Set(h)
    LayoutHelpers.AtLeftTopIn(b, parent, x, y)
    b.Depth:Set(parent.Depth() + 2)
    local t = UIUtil.CreateText(b, label, 16, UIUtil.bodyFont)
    t:DisableHitTest()
    t:SetColor('FFE6EEF5')
    t.Depth:Set(b.Depth() + 1)
    LayoutHelpers.AtCenterIn(t, b)
    b.HandleEvent = function(self, event)
        if event.Type == 'MouseEnter' then
            self:SetSolidColor(CPNET_ACCENT)
        elseif event.Type == 'MouseExit' then
            self:SetSolidColor(CPNET_BUTTON)
        elseif event.Type == 'ButtonPress' then
            pcall(function() PlaySound(Sound({ Bank = 'Interface', Cue = 'UI_Opt_Mini_Button_Click' })) end)
            onClick()
        end
        return true
    end
    table.insert(items, b)
    table.insert(items, t)
    return b
end

local function CPNetText(parent, items, text, size, color, x, y)
    local UIUtil = import('/lua/ui/uiutil.lua')
    local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
    local t = UIUtil.CreateText(parent, text, size, UIUtil.bodyFont)
    t:DisableHitTest()
    t:SetColor(color)
    t:SetDropShadow(true)
    t.Depth:Set(parent.Depth() + 2)
    LayoutHelpers.AtLeftTopIn(t, parent, x, y)
    table.insert(items, t)
    return t
end

-- my own choice: faction, color or team one step back or forward
function CPNetChange(what, delta)
    local mine = CPNetMine()
    if not mine or CPNet.started then return end
    local change = {}
    if what == 'faction' then
        change.Faction = math.mod(mine.faction + delta + 4, 4)
    elseif what == 'color' then
        local n = CPNetColors()
        change.Color = math.mod(mine.color + delta + n, n)
    elseif what == 'team' then
        change.Team = math.mod(mine.team - 1 + delta + 9, 9) + 1
    end
    if CPNet.host then
        CPNetApply(CPNet.myId, change)
    elseif CPNet.comm and CPNet.hostId then
        CPNet.comm:SendData(CPNet.hostId, { Type = 'CPSet', Change = change })
    end
end

function CPNetShow()
    local ok, err = pcall(function()
        local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
        local Bitmap = import('/lua/maui/bitmap.lua').Bitmap
        local frame = GetFrame(0)
        if not CPNet.panel then
            local p = Bitmap(frame)
            p:SetSolidColor('F20B1118')
            p.Depth:Set(frame:GetTopmostDepth() + 100)
            LayoutHelpers.FillParent(p, frame)
            p.items = {}
            p.HandleEvent = function(self, event)
                if event.Type == 'KeyDown' and (event.KeyCode == 13 or event.RawKeyCode == 13) and CPNet.host then
                    CPNetLaunch()
                    return true
                end
                if event.Type == 'KeyDown' and (event.KeyCode == 27 or event.RawKeyCode == 27) then
                    CPNetClose()
                    return true
                end
                return true
            end
            CPNet.panel = p
        end
        local p = CPNet.panel
        for _, c in p.items do pcall(function() c:Destroy() end) end
        p.items = {}
        local items = p.items
        local x0 = 80
        local title = LOC('<LOC CP_NET_TITLE>ROOM WITH FRIENDS')
        if CPNet.host then title = title .. '  -  ' .. LOC('<LOC CP_NET_YOU_HOST>you are the host') end
        CPNetText(p, items, title, 26, 'FFF2B33D', x0, 50)
        local view = CPNet.view or {}
        if view.map then
            local line = LOC('<LOC CP_NET_MAP>Map') .. ': ' .. tostring(view.map)
            if view.mode and view.mode ~= '' then
                local names = {
                    total = '<LOC CP_MG_TOTAL_TITLE>TOTAL WAR', arena = '<LOC CP_MG_ARENA_TITLE>EXPERIMENTAL ARENA',
                    defense = '<LOC CP_MG_DEF_TITLE>LAST LINE OF DEFENSE', domination = '<LOC CP_MG_DOM_TITLE>STRATEGIC DOMINATION',
                    supreme = '<LOC CP_MG_SUP_TITLE>SUPREME PROJECT', survival = '<LOC CP_MG_SURV_TITLE>ENDLESS SURVIVAL',
                    koth = '<LOC CP_MG_KOTH_TITLE>KING OF THE HILL', vip = '<LOC CP_MG_VIP_TITLE>ESCORT',
                    race = '<LOC CP_MG_RACE_TITLE>RESOURCE RACE', treasure = '<LOC CP_MG_TREASURE_TITLE>TREASURE HUNT',
                }
                line = line .. '   -   ' .. LOC('<LOC CP_NET_MODE>Mode') .. ': ' .. LOC(names[view.mode] or tostring(view.mode))
            end
            CPNetText(p, items, line, 16, 'FFB8C7D6', x0, 88)
        end
        local y = 120
        for _, l in CPNet.lines do
            CPNetText(p, items, l, 15, 'FFE6EEF5', x0, y)
            y = y + 20
        end
        y = math.max(y + 10, 190)
        -- the players: name, faction, color, team (your line has the buttons)
        CPNetText(p, items, LOC('<LOC CP_NET_PLAYER>Player'), 14, 'FF8FA3B8', x0, y)
        CPNetText(p, items, LOC('<LOC CP_NET_FACTION>Faction'), 14, 'FF8FA3B8', x0 + 330, y)
        CPNetText(p, items, LOC('<LOC CP_NET_COLOR>Color'), 14, 'FF8FA3B8', x0 + 560, y)
        CPNetText(p, items, LOC('<LOC CP_NET_TEAMS>Team'), 14, 'FF8FA3B8', x0 + 720, y)
        y = y + 24
        local shown = 0
        for i, s in view.slots or {} do
            if shown >= 16 then
                CPNetText(p, items, LOCF('<LOC CP_NET_MORE>... and %d more AI', table.getn(view.slots) - shown), 14, 'FF8FA3B8', x0, y)
                break
            end
            shown = shown + 1
            local mine = CPNet.myId and s.owner == CPNet.myId
            local who = s.name
            if s.kind == 'G' then who = LOC('<LOC CP_NET_FREE>(free: a friend can join; becomes AI)') end
            if s.kind == 'A' then who = who .. '  (' .. LOC('<LOC CP_NET_AI>AI') .. ')' end
            CPNetText(p, items, i .. '.  ' .. who, 17, mine and 'FF7CFF7C' or 'FFE6EEF5', x0, y + 4)
            local swatch = Bitmap(p)
            swatch:SetSolidColor(CPNetSwatch(s.faction, s.color))
            swatch.Width:Set(48)
            swatch.Height:Set(20)
            LayoutHelpers.AtLeftTopIn(swatch, p, x0 + 600, y + 5)
            swatch.Depth:Set(p.Depth() + 2)
            swatch:DisableHitTest()
            table.insert(items, swatch)
            if mine and not CPNet.started then
                CPNetButton(p, items, '<', x0 + 330, y, 28, 30, function() CPNetChange('faction', -1) end)
                CPNetText(p, items, CPNetFactionName(s.faction), 17, 'FFFFFFFF', x0 + 366, y + 4)
                CPNetButton(p, items, '>', x0 + 500, y, 28, 30, function() CPNetChange('faction', 1) end)
                CPNetButton(p, items, '<', x0 + 560, y, 28, 30, function() CPNetChange('color', -1) end)
                CPNetButton(p, items, '>', x0 + 660, y, 28, 30, function() CPNetChange('color', 1) end)
                CPNetButton(p, items, '<', x0 + 720, y, 28, 30, function() CPNetChange('team', -1) end)
                CPNetText(p, items, CPNetTeamName(s.team), 17, 'FFFFFFFF', x0 + 756, y + 4)
                CPNetButton(p, items, '>', x0 + 860, y, 28, 30, function() CPNetChange('team', 1) end)
            else
                CPNetText(p, items, CPNetFactionName(s.faction), 17, 'FFB8C7D6', x0 + 366, y + 4)
                CPNetText(p, items, CPNetTeamName(s.team), 17, 'FFB8C7D6', x0 + 756, y + 4)
            end
            y = y + 34
        end
        y = y + 16
        if CPNet.host and not CPNet.started then
            CPNetButton(p, items, LOC('<LOC CP_NET_START>START THE MATCH (ENTER)'), x0, y, 320, 40, function() CPNetLaunch() end)
            CPNetButton(p, items, LOC('<LOC CP_NET_LEAVE>LEAVE (ESC)'), x0 + 340, y, 200, 40, function() CPNetClose() end)
        elseif not CPNet.started then
            CPNetText(p, items, LOC('<LOC CP_NET_WAIT>Waiting for the host to start the match...'), 16, 'FFB8C7D6', x0, y + 8)
            CPNetButton(p, items, LOC('<LOC CP_NET_LEAVE>LEAVE (ESC)'), x0 + 420, y, 200, 40, function() CPNetClose() end)
        end
        p:AcquireKeyboardFocus(false)
    end)
    if not ok then
        WARN('*CommandProject room: ' .. tostring(err))
        for _, l in CPNet.lines do LOG('*CommandProject room: ' .. l) end
    end
end

local function CPNetStatus(text)
    LOG('*CommandProject room: ' .. text)
    table.insert(CPNet.lines, text)
    if table.getn(CPNet.lines) > 3 then table.remove(CPNet.lines, 1) end
    CPNetShow()
end

-- host: the room changed, everybody gets the new list
local function CPNetBroadcast()
    if not CPNet.host or not CPNet.info then return end
    CPNet.view = { slots = CPNetSlots(), map = CPNet.mapName, mode = CPNet.mode }
    pcall(function() CPNet.comm:BroadcastData({ Type = 'CPLobby', View = CPNet.view }) end)
    CPNetShow()
end

-- host: a player changed faction, color or team (a color already taken goes to the next free one)
function CPNetApply(owner, change)
    if not CPNet.info or CPNet.started then return end
    local colors = CPNetColors()
    for _, p in CPNet.info.teamInfo do
        if p.OwnerID == owner then
            local f = tonumber(change.Faction or '')
            if f and f >= 0 and f <= 3 then
                p.CPFaction = f
                if f >= 1 then p.Faction = f end
            end
            local c = tonumber(change.Color or '')
            if c then
                c = math.mod(math.max(0, c), colors)
                local step = 1
                if c < (p.PlayerColor or 0) then step = -1 end
                for tries = 1, colors do
                    local taken = false
                    for _, o in CPNet.info.teamInfo do
                        if o ~= p and not o.Civilian and o.PlayerColor == c then taken = true end
                    end
                    if not taken then break end
                    c = math.mod(c + step + colors, colors)
                end
                p.PlayerColor = c
                p.ArmyColor = c
            end
            local t = tonumber(change.Team or '')
            if t and t >= 1 and t <= 9 then p.Team = t end
        end
    end
    CPNetBroadcast()
end

-- the host starts the match for everybody: free friend bases become AI
function CPNetLaunch()
    if not CPNet.host or CPNet.started then return end
    CPNet.started = true
    local comm = CPNet.comm
    local hostID = comm:GetLocalPlayerID()
    local players = {}
    for _, p in CPNet.info.teamInfo do
        local q = table.copy(p)
        if q.CPGuest and not q.OwnerID then
            q.Human = false
            q.AIPersonality = CPNet.ai or 'Normal'
            q.PlayerName = GetRandomName(q.Faction, q.AIPersonality)
        end
        if q.CPFaction == 0 then q.Faction = GetRandomFaction() end
        if not q.OwnerID then q.OwnerID = hostID end
        q.CPGuest = nil
        q.CPFaction = nil
        q.Ready = true
        table.insert(players, q)
    end
    local options = table.copy(CPNet.info.scenarioInfo.Options or {})
    options.ScenarioFile = CPNet.info.scenarioInfo.file or CPNet.map
    local gameInfo = {
        GameOptions = options,
        PlayerOptions = players,
        Observers = {},
        GameMods = CPNet.info.scenarioMods or {},
    }
    LOG('*CommandProject room: starting with ' .. table.getn(players) .. ' armies')
    CPNetStatus(LOC('<LOC CP_NET_STARTING>Starting...'))
    comm:BroadcastData({ Type = 'CPLaunch', GameInfo = gameInfo })
    comm:LaunchGame(gameInfo)
end

-- opens the room. o = { host = true, map, spec, port, name, mode } or { host = false, address, name }
function CPNetOpen(o)
    local Comm = import('/lua/ui/lobby/lobbyComm.lua')
    local Prefs = import('/lua/user/prefs.lua')
    local name = o.name or Prefs.GetFromCurrentProfile('Name') or 'Player'
    CPNet.host = o.host and true or false
    CPNet.map = o.map
    CPNet.lines = {}
    CPNet.started = false
    if CPNet.host then
        CPNet.info = CPBigMatchSession(o.map, o.spec)
        for _, p in CPNet.info.teamInfo do
            if p.Human and not p.CPGuest then CPNet.me = p end
        end
        if not CPNet.me then error('no base for the host') end
        CPNet.me.PlayerName = name
        CPNet.me.CPFaction = CPNet.me.Faction
        local scen = CPNet.info.scenarioInfo or {}
        CPNet.mapName = LOC(scen.name or o.map or '')
        CPNet.mode = o.mode or (scen.Options and scen.Options.CPMode) or ''
    end
    -- more than the game's 8 people: room for every friend base
    Comm.maxConnections = 31
    local port = CPNet.host and (tonumber(o.port or '') or 15000) or 0
    local comm = Comm.CreateLobbyComm('UDP', port, name, nil, nil)
    if not comm then error('could not open the network (port ' .. tostring(port) .. ')') end
    CPNet.comm = comm

    comm.Hosting = function(self)
        CPNet.myId = self:GetLocalPlayerID()
        CPNet.me.OwnerID = CPNet.myId
        CPNetStatus(LOCF('<LOC CP_NET_OPEN>Open on port %d. Friends join with the launcher invite (Big match -> Invite) or with your IP.', port))
        CPNetBroadcast()
    end
    comm.ConnectionFailed = function(self, reason)
        CPNetStatus(LOC('<LOC CP_NET_FAILED>Could not connect:') .. ' ' .. tostring(reason))
    end
    comm.ConnectionToHostEstablished = function(self, ourID, hostID)
        CPNet.myId = ourID
        CPNet.hostId = hostID
        CPNetStatus(LOC('<LOC CP_NET_CONNECTED>Connected to the host. Pick your faction, color and team.'))
        self:SendData(hostID, { Type = 'CPHello', Name = name })
    end
    comm.Ejected = function(self, reason)
        CPNetStatus(LOC('<LOC CP_NET_REFUSED>The host refused:') .. ' ' .. tostring(reason))
    end
    comm.PeerDisconnected = function(self, peerName, uid)
        if CPNet.host and not CPNet.started then
            for _, p in CPNet.info.teamInfo do
                if p.CPGuest and p.OwnerID == uid then
                    p.OwnerID = nil
                    p.PlayerName = 'Convidado'
                end
            end
            CPNetStatus(LOCF('<LOC CP_NET_LEFT>%s left', tostring(peerName)))
            CPNetBroadcast()
        elseif not CPNet.host then
            CPNetStatus(LOC('<LOC CP_NET_HOST_LEFT>The host left.'))
        end
    end
    comm.LaunchFailed = function(self, reason)
        CPNet.started = false
        CPNetStatus(LOC('<LOC CP_NET_NOSTART>The match did not start:') .. ' ' .. tostring(reason))
    end
    comm.DataReceived = function(self, data)
        if CPNet.host and data.Type == 'CPHello' and not CPNet.started then
            local slot = nil
            for _, p in CPNet.info.teamInfo do
                if p.CPGuest and not p.OwnerID then
                    slot = p
                    break
                end
            end
            if not slot then
                self:EjectPeer(data.SenderID, 'full')
                return
            end
            slot.OwnerID = data.SenderID
            slot.PlayerName = tostring(data.Name or data.SenderName or 'Amigo')
            slot.CPFaction = 0
            CPNetStatus(LOCF('<LOC CP_NET_JOINED>%s joined', slot.PlayerName))
            CPNetBroadcast()
        elseif CPNet.host and data.Type == 'CPSet' and type(data.Change) == 'table' then
            CPNetApply(data.SenderID, data.Change)
        elseif not CPNet.host and data.Type == 'CPLobby' and type(data.View) == 'table' then
            CPNet.view = data.View
            CPNetShow()
        elseif not CPNet.host and data.Type == 'CPLaunch' and data.GameInfo then
            CPNet.started = true
            CPNetStatus(LOC('<LOC CP_NET_STARTING>Starting...'))
            self:LaunchGame(data.GameInfo)
        end
    end

    if CPNet.host then
        comm:HostGame()
    else
        if not o.address or o.address == '' then error('no address') end
        pcall(function()
            Prefs.SetToCurrentProfile('CPNetLast', o.address)
            if SavePreferences then SavePreferences() end
        end)
        CPNetStatus(LOCF('<LOC CP_NET_CONNECTING>Connecting to %s...', o.address))
        comm:JoinGame(o.address, nil, nil)
    end
    CPNetShow()
end

-- invite from the launcher: /cphost <port> or /cpjoin <address> (and /cpname <name>)
function CPNetStart(mapName, spec)
    CPNet.fromMenu = false
    if HasCommandLineArg('/cphost') then
        CPNetOpen({ host = true, map = mapName, spec = spec, port = CPArg('/cphost'), name = CPArg('/cpname') })
    else
        CPNetOpen({ host = false, address = CPArg('/cpjoin'), name = CPArg('/cpname') })
    end
end

-- Battle -> "Sala com amigos": the big match choices kept in the room, the other bases for friends
function CPNetHostFromMenu(defaultMap)
    local ok, err = pcall(function()
        local map = CPBMGet('map')
        if not map or not import('/lua/ui/maputil.lua').LoadScenario(map) then map = defaultMap end
        CPBigMatchQuick(map, CPBMGet('players'), CPBMGet('teams'), CPBMGet('ai'), CPBMGet('faction'), CPBMGet('victory'), CPBMGet('units'), true)
    end)
    if not ok then
        WARN('*CommandProject room: ' .. tostring(err))
        CPNetStatus(tostring(err))
    end
end

-- Multiplayer -> "Entrar na sala de um amigo": asks the address (the last one, or the launcher
-- group's host, already written)
function CPNetJoinFromMenu(address)
    local ok, err = pcall(function()
        local UIUtil = import('/lua/ui/uiutil.lua')
        local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
        local Bitmap = import('/lua/maui/bitmap.lua').Bitmap
        local Edit = import('/lua/maui/edit.lua').Edit
        local frame = GetFrame(0)
        local p = Bitmap(frame)
        p:SetSolidColor('F20B1118')
        p.Depth:Set(frame:GetTopmostDepth() + 100)
        LayoutHelpers.FillParent(p, frame)
        local items = {}
        CPNetText(p, items, LOC('<LOC CP_NET_JOIN_TITLE>JOIN A FRIEND\'S ROOM'), 26, 'FFF2B33D', 80, 60)
        CPNetText(p, items, LOC('<LOC CP_NET_JOIN_HINT>The host\'s address (IP or IP:port), from the launcher invite. ENTER joins, ESC goes back.'), 16, 'FFB8C7D6', 80, 100)
        local box = Bitmap(p)
        box:SetSolidColor('FF1C2733')
        box.Width:Set(420)
        box.Height:Set(40)
        LayoutHelpers.AtLeftTopIn(box, p, 80, 140)
        box.Depth:Set(p.Depth() + 1)
        local e = Edit(box)
        e.Width:Set(400)
        e.Height:Set(30)
        LayoutHelpers.AtLeftTopIn(e, box, 10, 6)
        e.Depth:Set(box.Depth() + 1)
        e:SetFont(UIUtil.bodyFont, 20)
        e:SetForegroundColor('FFFFFFFF')
        e:ShowBackground(false)
        e:SetMaxChars(60)
        local last = address
        if not last or last == '' then
            local okp, v = pcall(function() return import('/lua/user/prefs.lua').GetFromCurrentProfile('CPNetLast') end)
            if okp and v then last = v end
        end
        e:SetText(last or '')
        local function go(text)
            text = tostring(text or '')
            if text == '' then return end
            p:Destroy()
            CPNet.fromMenu = true
            local okj, errj = pcall(CPNetOpen, { host = false, address = text })
            if not okj then WARN('*CommandProject room: ' .. tostring(errj)) end
        end
        e.OnEnterPressed = function(self, text)
            go(text)
            return true
        end
        e.OnEscPressed = function(self, text)
            p:Destroy()
            return true
        end
        CPNetButton(p, items, LOC('<LOC CP_NET_JOIN>JOIN'), 520, 140, 160, 40, function() go(e:GetText()) end)
        CPNetButton(p, items, LOC('<LOC CP_NET_BACK>BACK'), 700, 140, 120, 40, function() p:Destroy() end)
        e:AcquireFocus()
    end)
    if not ok then WARN('*CommandProject room (join): ' .. tostring(err)) end
end

-- Multiplayer -> "Entrar na sala de <anfitrião>": the host of the launcher's last invite
function CPNetJoinDirect(address)
    CPNet.fromMenu = true
    local ok, err = pcall(CPNetOpen, { host = false, address = address })
    if not ok then WARN('*CommandProject room: ' .. tostring(err)) end
end

---------------------------------------------------------------------------- big match screen
-- Battle -> "PARTIDA GRANDE": the whole big match setup on one screen made in Lua (the game's
-- lobby only runs its own commands, so buttons placed in it cannot start anything). Choices are
-- kept in the game profile (CPBMSet) like before; the maps come straight from the game's files.
local CPBMUI = { panel = false, maps = false, accent = 'FF2B8CFF', page = 0 }

local function CPHexColor(hex)
    hex = tostring(hex or '')
    if string.sub(hex, 1, 1) == '#' then hex = string.sub(hex, 2) end
    if string.len(hex) == 6 then return 'FF' .. string.upper(hex) end
    return 'FF2B8CFF'
end

local function CPBigMaps()
    if CPBMUI.maps then return CPBMUI.maps end
    local out = {}
    local MapUtil = import('/lua/ui/maputil.lua')
    local ok, files = pcall(DiskFindFiles, '/maps', '*_scenario.lua')
    if ok and files then
        for _, f in files do
            local okl, scen = pcall(MapUtil.LoadScenario, f)
            if okl and scen and scen.Configurations and scen.Configurations.standard and scen.Configurations.standard.teams then
                local armies = scen.Configurations.standard.teams[1].armies
                if armies and table.getn(armies) >= 2 and (scen.type == 'skirmish' or scen.type == 'cp_bigmatch') then
                    table.insert(out, { path = f, name = LOC(scen.name or f), bases = table.getn(armies), size = (scen.size and scen.size[1]) or 0 })
                end
            end
        end
    end
    table.sort(out, function(a, b)
        if a.bases ~= b.bases then return a.bases > b.bases end
        return tostring(a.name) < tostring(b.name)
    end)
    CPBMUI.maps = out
    return out
end

local function CPUIButton(parent, items, label, x, y, w, h, on, onClick, size)
    local UIUtil = import('/lua/ui/uiutil.lua')
    local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
    local Bitmap = import('/lua/maui/bitmap.lua').Bitmap
    local accent = CPBMUI.accent
    -- borda (na cor) e o miolo por cima
    local border = Bitmap(parent)
    border:SetSolidColor(on and accent or 'FF2A3A4C')
    border.Width:Set(w)
    border.Height:Set(h)
    LayoutHelpers.AtLeftTopIn(border, parent, x, y)
    border.Depth:Set(parent.Depth() + 2)
    local fill = Bitmap(border)
    local idle = on and ('C0' .. string.sub(accent, 3)) or 'FF121A24'
    fill:SetSolidColor(idle)
    fill.Width:Set(w - 2)
    fill.Height:Set(h - 2)
    LayoutHelpers.AtLeftTopIn(fill, border, 1, 1)
    fill.Depth:Set(border.Depth() + 1)
    fill:DisableHitTest()
    local t = UIUtil.CreateText(border, label, size or 15, UIUtil.bodyFont)
    t:DisableHitTest()
    t:SetColor('FFFFFFFF')
    t:SetDropShadow(true)
    t.Depth:Set(fill.Depth() + 1)
    LayoutHelpers.AtCenterIn(t, border)
    border.HandleEvent = function(self, event)
        if event.Type == 'MouseEnter' then
            fill:SetSolidColor(on and accent or ('60' .. string.sub(accent, 3)))
            self:SetSolidColor(accent)
        elseif event.Type == 'MouseExit' then
            fill:SetSolidColor(idle)
            self:SetSolidColor(on and accent or 'FF2A3A4C')
        elseif event.Type == 'ButtonPress' then
            pcall(function() PlaySound(Sound({ Bank = 'Interface', Cue = 'UI_Opt_Mini_Button_Click' })) end)
            onClick()
        end
        return true
    end
    table.insert(items, border)
    table.insert(items, fill)
    table.insert(items, t)
    return border
end

local CPBM_MODES = {
    { '', 'demoralization', '<LOC CP_BM_NORMAL>NORMAL' }, { '', 'domination', '<LOC CP_BM_ALL>DESTROY ALL' }, { '', 'sandbox', '<LOC CP_BM_ENDLESS>ENDLESS' },
    { 'domination', '', '<LOC CP_MG_DOM_TITLE>STRATEGIC DOMINATION' }, { 'koth', '', '<LOC CP_MG_KOTH_TITLE>KING OF THE HILL' },
    { 'arena', '', '<LOC CP_MG_ARENA_TITLE>EXPERIMENTAL ARENA' }, { 'defense', '', '<LOC CP_MG_DEF_TITLE>LAST LINE OF DEFENSE' },
    { 'survival', '', '<LOC CP_MG_SURV_TITLE>ENDLESS SURVIVAL' }, { 'vip', '', '<LOC CP_MG_VIP_TITLE>ESCORT' },
    { 'race', '', '<LOC CP_MG_RACE_TITLE>RESOURCE RACE' }, { 'treasure', '', '<LOC CP_MG_TREASURE_TITLE>TREASURE HUNT' },
    { 'total', '', '<LOC CP_MG_TOTAL_TITLE>TOTAL WAR' }, { 'supreme', '', '<LOC CP_MG_SUP_TITLE>SUPREME PROJECT' },
}
local CPBM_EXTRAS = {
    { '', false, '<LOC CP_BM_NONE>NONE' }, { '', true, '<LOC CP_BM_EVENTS>EVENTS' }, { 'hp,res,cdr', true, '<LOC CP_BM_CHAOS>CHAOS' },
    { 'air', false, '<LOC CP_MG_MUT_AIR>Air only' }, { 'hp,cdr', false, '<LOC CP_BM_TANKS>TANKS' },
}

function CPBigMatchScreenClose()
    if CPBMUI.panel then pcall(function() CPBMUI.panel:Destroy() end) end
    CPBMUI.panel = false
end

function CPBigMatchScreenDraw()
    local ok, err = pcall(function()
        local UIUtil = import('/lua/ui/uiutil.lua')
        local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
        local Bitmap = import('/lua/maui/bitmap.lua').Bitmap
        local frame = GetFrame(0)
        if not CPBMUI.panel then
            local p = Bitmap(frame)
            p:SetSolidColor('F00A1017')
            p.Depth:Set(frame:GetTopmostDepth() + 100)
            LayoutHelpers.FillParent(p, frame)
            p.items = {}
            p.HandleEvent = function(self, event)
                if event.Type == 'KeyDown' and (event.KeyCode == 27 or event.RawKeyCode == 27) then
                    CPBigMatchScreenClose()
                elseif event.Type == 'KeyDown' and (event.KeyCode == 13 or event.RawKeyCode == 13) then
                    CPBigMatchScreenStart()
                end
                return true
            end
            CPBMUI.panel = p
        end
        local p = CPBMUI.panel
        for _, c in p.items do pcall(function() c:Destroy() end) end
        p.items = {}
        local items = p.items
        local W, H = frame.Width(), frame.Height()
        local s = math.min(W / 1920, H / 1080)
        if s <= 0 then s = 1 end
        local function X(v) return math.floor(v * s) end
        local function text(t, size, color, x, y)
            local c = UIUtil.CreateText(p, t, math.max(10, X(size)), UIUtil.bodyFont)
            c:DisableHitTest()
            c:SetColor(color)
            c:SetDropShadow(true)
            c.Depth:Set(p.Depth() + 2)
            LayoutHelpers.AtLeftTopIn(c, p, X(x), X(y))
            table.insert(items, c)
        end
        local function bar(x, y, w, h, color)
            local b = Bitmap(p)
            b:SetSolidColor(color)
            b.Width:Set(X(w))
            b.Height:Set(math.max(1, X(h)))
            LayoutHelpers.AtLeftTopIn(b, p, X(x), X(y))
            b.Depth:Set(p.Depth() + 1)
            b:DisableHitTest()
            table.insert(items, b)
        end
        local function button(label, x, y, w, h, on, fn, size)
            CPUIButton(p, items, label, X(x), X(y), X(w), X(h), on, fn, math.max(10, X(size or 15)))
        end
        -- cabeçalho
        bar(0, 0, 1920, 110, 'C0101A26')
        bar(0, 110, 1920, 2, CPBMUI.accent)
        text(LOC('<LOC CP_BM_TITLE>BIG MATCH'), 40, 'FFFFFFFF', 80, 30)
        text(LOC('<LOC CP_BM_SUB>More than 8 players, minigames and mutators. Your choices are kept.'), 17, 'FFB8C7D6', 82, 78)
        -- coluna das opções
        local x0, y = 80, 140
        local function section(title, list, cols, w)
            text(title, 16, 'FF8FA3B8', x0, y)
            y = y + 26
            local gap = 8
            for i, it in list do
                local c = math.mod(i - 1, cols)
                local r = math.floor((i - 1) / cols)
                button(it[1], x0 + c * (w + gap), y + r * 44, w, 38, it[2], it[3], 15)
            end
            y = y + math.ceil(table.getn(list) / cols) * 44 + 14
        end
        local players = CPBMGet('players')
        local list = {}
        for _, n0 in { 10, 12, 16, 20, 24, 32 } do
            local n = n0
            table.insert(list, { tostring(n), players == n, function() CPBMSet('players', n) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_PLAYERS>PLAYERS'), list, 6, 120)
        local teams = CPBMGet('teams')
        list = {}
        for _, it in { { 2, '<LOC CP_BM_T2>2 TEAMS' }, { 3, '<LOC CP_BM_T3>3 TEAMS' }, { 4, '<LOC CP_BM_T4>4 TEAMS' }, { 0, '<LOC CP_BM_FFA>FREE FOR ALL' } } do
            local v = it[1]
            table.insert(list, { LOC(it[2]), teams == v, function() CPBMSet('teams', v) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_TEAMS>TEAMS'), list, 4, 184)
        local ai = CPBMGet('ai')
        list = {}
        for _, it in { { 'Easy', '<LOC CP_BM_EASY>EASY' }, { 'Normal', '<LOC CP_BM_NORMALAI>NORMAL' }, { 'Hard', '<LOC CP_BM_HARD>HARD' }, { 'Cheat', '<LOC CP_BM_CHEAT>EXTREME' } } do
            local v = it[1]
            table.insert(list, { LOC(it[2]), ai == v, function() CPBMSet('ai', v) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_AI>AI DIFFICULTY'), list, 4, 184)
        local faction = CPBMGet('faction')
        list = {}
        for i, nm in { '<LOC CP_NET_RANDOM>Random', 'UEF', 'Cybran', 'Illuminate' } do
            local v = i - 1
            table.insert(list, { LOC(nm), faction == v, function() CPBMSet('faction', v) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_FACTION>YOUR FACTION'), list, 4, 184)
        local mode, victory = CPBMGet('mode') or '', CPBMGet('victory')
        list = {}
        for _, it in CPBM_MODES do
            local m, v = it[1], it[2]
            local on = (m ~= '' and mode == m) or (m == '' and mode == '' and victory == v)
            table.insert(list, { LOC(it[3]), on, function() CPBMSetMode(m, v) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_MODE>MODE (VICTORY OR MINIGAME)'), list, 3, 248)
        local mut, ev = CPBMGet('mut') or '', CPBMGet('events') == true
        list = {}
        for _, it in CPBM_EXTRAS do
            local m, e = it[1], it[2]
            table.insert(list, { LOC(it[3]), mut == m and ev == e, function() CPBMSetExtras(m, e) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_EXTRAS>EXTRAS (MUTATORS AND EVENTS)'), list, 5, 145)
        local units = CPBMGet('units')
        list = {}
        for _, n0 in { 250, 500, 1000, 1500 } do
            local n = n0
            table.insert(list, { tostring(n), units == n, function() CPBMSet('units', n) CPBigMatchScreenDraw() end })
        end
        section(LOC('<LOC CP_BM_UNITS>UNIT CAP'), list, 4, 184)
        -- coluna dos mapas
        local mx = 900
        local maps = CPBigMaps()
        local chosen = CPBMGet('map')
        local found = false
        for _, m in maps do
            if m.path == chosen then found = true end
        end
        if not found and maps[1] then chosen = maps[1].path end
        text(LOC('<LOC CP_BM_MAP>MAP'), 16, 'FF8FA3B8', mx, 140)
        local per = 14
        local pages = math.max(1, math.ceil(table.getn(maps) / per))
        if CPBMUI.page >= pages then CPBMUI.page = 0 end
        local first = CPBMUI.page * per
        for i = 1, per do
            local m = maps[first + i]
            if not m then break end
            local label = m.bases .. '   ' .. tostring(m.name)
            if m.size and m.size > 0 then label = label .. '   (' .. m.size .. ')' end
            local path = m.path
            button(label, mx, 166 + (i - 1) * 46, 620, 40, path == chosen, function() CPBMSet('map', path) CPBigMatchScreenDraw() end, 15)
        end
        if pages > 1 then
            local py = 166 + per * 46 + 6
            button('<', mx, py, 60, 36, false, function() CPBMUI.page = math.mod(CPBMUI.page - 1 + pages, pages) CPBigMatchScreenDraw() end)
            text((CPBMUI.page + 1) .. ' / ' .. pages, 16, 'FFB8C7D6', mx + 80, py + 8)
            button('>', mx + 150, py, 60, 36, false, function() CPBMUI.page = math.mod(CPBMUI.page + 1, pages) CPBigMatchScreenDraw() end)
        end
        if table.getn(maps) == 0 then text(LOC('<LOC CP_BM_NOMAPS>No maps found.'), 16, 'FFFF6A5A', mx, 170) end
        -- rodapé
        bar(0, 960, 1920, 2, CPBMUI.accent)
        bar(0, 962, 1920, 118, 'C0101A26')
        button(LOC('<LOC CP_BM_BACK>BACK (ESC)'), 80, 990, 260, 56, false, function() CPBigMatchScreenClose() end, 18)
        button(LOC('<LOC CP_BM_FRIENDS>ROOM WITH FRIENDS'), 1080, 990, 320, 56, false, function()
            local map = chosen
            CPBigMatchScreenClose()
            CPNetHostFromMenu(map)
        end, 18)
        button(LOC('<LOC CP_BM_START>START (ENTER)'), 1420, 990, 420, 56, true, function() CPBigMatchScreenStart() end, 20)
        CPBMUI.chosen = chosen
        p:AcquireKeyboardFocus(false)
    end)
    if not ok then WARN('*CommandProject big match screen: ' .. tostring(err)) end
end

function CPBigMatchScreenStart()
    local map = CPBMUI.chosen
    if not map then return end
    CPBMSet('map', map)
    CPBigMatchScreenClose()
    local ok, err = pcall(CPBigMatchFromMenu, map)
    if not ok then WARN('*CommandProject big match screen: ' .. tostring(err)) end
end

-- Battle -> "PARTIDA GRANDE" (accent = the start screen color, '#rrggbb')
function CPBigMatchScreen(accent)
    CPBMUI.accent = CPHexColor(accent)
    CPBMUI.maps = false
    CPBigMatchScreenDraw()
end
